import{_ as n,l as r,o as s,b as i,q as p,d as o,f as l,m as a}from"./chunks/framework.Tf23FRXt.js";const B=JSON.parse('{"title":"究极神兵破坏作战","description":"","frontmatter":{},"headers":[],"relativePath":"duty/830.htm.md","filePath":"duty/830.md","lastUpdated":1791098838000}'),d={name:"duty/830.htm.md"};function m(S,t,u,_,f,O){const e=r("Role");return s(),i("div",null,[t[3]||(t[3]=p('<h1 id="究极神兵破坏作战" tabindex="-1">究极神兵破坏作战</h1><p>开场神兵带 3 个 buff，分别代表土神、火神和风神，按血量分为 3 个阶段，会使用三神的标志性技能：</p><ul><li>土神：冲拳和流沙，BOSS 也会复读土神的冲拳，出啥躲啥即可。</li><li>火神：地火，同时会出现击退接地火的情况，击退后注意立刻回场中。</li><li>风神：风眼 + 巨大范围 AOE，在场地中央没有风眼的区域里找不会被 AOE 打到的安全点即可。</li></ul><p>三神阶段打完后进转场动画，动画结束后进入 P2</p><p>P2 开始不久，BOSS 会使用直线激光技能，BOSS 在地上投射绿色的激光，然后激光炸 AOE 伤害，注意地面，躲开有激光的地方。</p><p>其他需要注意的技能有：</p><ul><li><mark>以太波动</mark>：BOSS 读条后，场地上出现两两连线的 4 个球，球会慢慢靠近。需要有人去撞球，只要撞掉连线中的其中一个球，另一个球会自动消失，撞球时会造成小范围的 AOE 伤害。如果不撞球的话，两个球撞到一起会形成全场 AOE 伤害。</li><li><mark>攻城炮</mark>：BOSS 读条结束后，向其正面方向发射宽度等身的超宽直线 AOE，发现读条或蓄力动作时注意到 BOSS 两侧、背后躲避。经常和分摊或其他需要集合的技能形成连击。</li><li>场地四角出现落点提示： 场地中央受到伤害最小。</li></ul>',7)),o("p",null,[t[0]||(t[0]=l("整场战斗有大量各种形状的 AOE，或者连续伤害，",-1)),a(e,{name:"healer"}),t[1]||(t[1]=l("治疗需要时刻注意团队血线，",-1)),a(e,{name:"tank"}),a(e,{name:"dps"}),t[2]||(t[2]=l("其他人可尽可能使用降低团队所受伤害的技能来帮助治疗。",-1))]),t[4]||(t[4]=o("p",null,"BOSS 血量压到极低之后，会回到中场开始读条团灭技。此时 NPC 会出现，并给玩家上增伤 buff，如果有大伤害技能的话，请等待上好 buff 之后再使用。",-1))])}const E=n(d,[["render",m]]);export{B as __pageData,E as default};
